local SettingRefBase = require('Game.Setting.SettingRefBase')

---@class EquipAttrVo
local EquipAttrVo = Class("EquipAttrVo", SettingRefBase)
local base = SettingRefBase
local ParseUtils = CS.ParseUtils

---__int
function EquipAttrVo:__init()
    self.equipAttId = nil
    self.attrAdditionId = nil
    self.type = nil
    self.attrNum = nil
    self.isRandom = nil
end


---FillVo
---@param row TableML.TableFileRow
function EquipAttrVo:FillVo(row)
    base.FillVo(self, row)
    -- AttrAdditionIdType
    self.equipAttId = parse_number(row, "equipAttId", 0)
    self.attrAdditionId = parse_number(row, "attAddTypeId", 0)
    self.type = parse_number(row, "equipAttPool", 0)
    self.isRandom = parse_number(row, "isRandom", 0)


    local qualities = ParseUtils.ParseListIntByHeaderName(row, "quality")
    local basicsMin = ParseUtils.ParseListFloatByHeaderName(row, "equipBaseNumMin")
    local basicsMax = ParseUtils.ParseListFloatByHeaderName(row, "equipBaseNumMax")
    local grows = ParseUtils.ParseListFloatByHeaderName(row, "equipGrowPre")
    local stars = ParseUtils.ParseListIntByHeaderName(row, "star")

    local qualitiesCount = qualities.Count
    if qualitiesCount > 0 then
        local len = math.min(qualitiesCount, basicsMin.Count)
        local attrNum = {}
        for i = 0, len - 1 do
            local quality = qualities[i];
            attrNum[tostring(quality)] = {
                quality = quality,
                baseMin = basicsMin[i],
                baseMax = basicsMax[i],
            }
        end
        self.attrNum = attrNum
    end

    local starsCount = stars.Count
    if starsCount > 0 then
        local len = math.min(starsCount, grows.Count)
        local growT = {}
        for i = 0, len - 1 do
            local star = stars[i];
            growT[tostring(star)] = {
                star = star,
                growPre = grows[i]
            }
        end
        self.grows = growT
    end

    self.stars = stars

    self.ladderRiseAttrs = {
        {
            ---类型id
            parse_number(row, "firstTypeId", 0),
            ---类型最大值
            parse_number(row, "firstTypeNum", 0)
        },
        {
            parse_number(row, "secondTypeId", 0),
            parse_number(row, "secondTypeNum", 0)

        }
    }
end

function EquipAttrVo:__delete()
    self.equipAttId = nil
    self.attrAdditionId = nil
    self.type = nil
    self.attrNum = nil
    self.grows = nil
    self.isRandom = nil
end

return EquipAttrVo